// Imports the precomputed case data and the orb's voice/sfx manifests from web/orb
// (generated by the backend's scripts/cases-orb.ts, voice-orb.ts and sfx-orb.ts) as JSON.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import vm from "node:vm";

const orb = fileURLToPath(new URL("../../web/orb/", import.meta.url));
const out = fileURLToPath(new URL("../src/data/", import.meta.url));
const load = (file) => {
  const window = {};
  vm.runInNewContext(readFileSync(orb + file, "utf8"), { window });
  return window;
};
const json = (name, value) => writeFileSync(out + name, JSON.stringify(value, null, 1) + "\n");

json("cases.json", load("data/cases.js").ORB_CASES);
json("voice.json", load("voice/manifest.js").ORB_VOICE);
json("sfx.json", load("sfx/manifest.js").ORB_SFX);
console.log("Imported cases, voice and sfx manifests into src/data/");
